    keys are merged with a dot in between.
    """
def flatten_dict(dct: Any, key_string: Any = "") -> object {
    result = [];
    for key in dct {
        updated_key_string = key_string + key + ".";
        if isinstance(dct[key], `dict) {
            result += flatten_dict(dct[key], updated_key_string);
